<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/auth.php';require_login();
$type=($_GET['type']??'IN')==='OUT'?'OUT':'IN';$title=$type==='IN'?'Barang Masuk':'Barang Keluar';
if($_SERVER['REQUEST_METHOD']==='POST'){$type=($_POST['type']??'IN')==='OUT'?'OUT':'IN';$title=$type==='IN'?'Barang Masuk':'Barang Keluar';$pid=filter_var($_POST['product_id']??null,FILTER_VALIDATE_INT);$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$note=trim($_POST['note']??'');
 try{if(!$pid||!$qty||$qty<=0)throw new Exception('Produk dan jumlah harus valid.');$pdo->beginTransaction();$s=$pdo->prepare('SELECT stock FROM products WHERE id=? FOR UPDATE');$s->execute([$pid]);$p=$s->fetch();if(!$p)throw new Exception('Produk tidak ditemukan.');if($type==='OUT'&&$qty>(int)$p['stock'])throw new Exception('Stok tidak cukup untuk barang keluar.');$delta=$type==='IN'?$qty:-$qty;$u=$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=?');$u->execute([$delta,$pid]);$i=$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,type,quantity,note) VALUES(?,?,?,?,?)');$i->execute([$pid,$_SESSION['user']['id'],$type,$qty,$note]);$pdo->commit();$_SESSION['flash']=$title.' berhasil dicatat.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['flash']=$e->getMessage()?:'Transaksi gagal diproses.';}header('Location: stock.php?type='.$type);exit;}
$products=$pdo->query('SELECT id,sku,name,stock FROM products ORDER BY name')->fetchAll();$s=$pdo->prepare('SELECT sm.*,p.name product_name,p.sku,u.username FROM stock_movements sm JOIN products p ON p.id=sm.product_id JOIN users u ON u.id=sm.user_id WHERE sm.type=? ORDER BY sm.id DESC LIMIT 50');$s->execute([$type]);$rows=$s->fetchAll();$pageTitle=$title;include __DIR__.'/includes/header.php';?>
<div class="grid-2"><section class="panel"><div class="panel-head"><h2>Catat <?= strtolower($title) ?></h2><span class="badge <?= $type==='IN'?'green':'purple' ?>"><?= $type ?></span></div><form method="post"><input type="hidden" name="type" value="<?= $type ?>"><div class="form-grid"><div class="field full"><label>Produk *</label><select name="product_id" required><option value="">Pilih produk</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>"><?= h($p['sku'].' — '.$p['name'].' (stok: '.$p['stock'].')') ?></option><?php endforeach; ?></select></div><div class="field full"><label>Jumlah unit *</label><input type="number" name="quantity" min="1" step="1" required></div><div class="field full"><label>Catatan</label><textarea name="note" rows="3" maxlength="255" placeholder="Catatan transaksi (opsional)"></textarea></div></div><div class="form-actions"><button class="btn">Simpan transaksi</button><a class="btn secondary" href="?type=<?= $type==='IN'?'OUT':'IN' ?>">Beralih ke <?= $type==='IN'?'barang keluar':'barang masuk' ?></a></div></form><p class="muted" style="margin-top:15px">Stok dan histori diperbarui dalam satu database transaction. Barang keluar tidak boleh melebihi stok.</p></section><section class="panel"><div class="panel-head"><h2>Aturan transaksi</h2></div><div class="stat-number"><?= count($rows) ?></div><div class="muted">Transaksi <?= strtolower($title) ?> terakhir (maks. 50)</div><p class="muted">Setiap transaksi mencatat produk, pengguna, jenis, jumlah, catatan, dan waktu.</p></section></div>
<section class="panel"><div class="panel-head"><h2>Histori <?= $title ?></h2></div><div class="table-wrap"><table><thead><tr><th>WAKTU</th><th>PRODUK</th><th>JUMLAH</th><th>PENGGUNA</th><th>CATATAN</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="5" class="empty">Belum ada transaksi.</td></tr><?php else: foreach($rows as $r): ?><tr><td><?= date('d M Y H:i',strtotime($r['created_at'])) ?></td><td class="product-name"><?= h($r['product_name']) ?><div class="muted"><?= h($r['sku']) ?></div></td><td><span class="badge <?= $type==='IN'?'green':'purple' ?>"><?= $type==='IN'?'+':'−' ?><?= (int)$r['quantity'] ?></span></td><td><?= h($r['username']) ?></td><td><?= h($r['note']??'—') ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
<?php include __DIR__.'/includes/footer.php';?>